def backfill_stages(apps, schema_editor):
    """Every existing call gets its first stage. Milestones recorded before stages existed keep an empty stage:
    the registry is append-only (no UPDATE on milestones), and an empty stage reads as the first one."""
    PortCall = apps.get_model("registry", "PortCall")
    CallStage = apps.get_model("registry", "CallStage")
    for call in PortCall.objects.all().iterator():
        if CallStage.objects.filter(call=call).exists():
            continue
        operations = [c for c in call.template_uses.values_list("template_version__template__code", flat=True) if c != "M0"]
        done = call.status in ("DEPARTED", "CLOSED", "ARCHIVED")
        CallStage.objects.create(
            call=call, order=1, berth_kind=call.requested_berth_kind, berth=call.berth, operations=operations,
            planned_from=call.etb, planned_to=call.etd, atb=call.atb, atd=call.atd if done else None,
            status="DONE" if done else "CURRENT", created_by=call.created_by, created_at=call.created_at,
        )


